"""Who closes the gap's report, reports/closure.md, and its JSON. Generated by `scripts/build_closure.py`.

One table per currency: at each of the IC's horizons, the slope of the
market's, the rule's and the policy rate's change on the de-meaned gap, each
with its Newey-West t, then the gap's own slope, the share of the edge closed,
the rule's part of the closing and the rule's non-overlapping range
(`closure.py` has the definitions). Under it, the reading at the longest
horizon, a template filled from the fit, and the bins the explorer draws.
The policy rate's direction is worded only where its t clears 1.96
(`credit.Z95`).
"""

import numpy as np
import pandas as pd
from policypath import credit
from policypath.report.coverage import table
from policypath.report.credit import jsonable
from policypath.report.onepager import ORDINAL

HEADER = "Generated by `scripts/build_closure.py` from `data/panel/`. Do not edit by hand."
WHO = {"the rule": "mostly by the rule", "the market": "mostly by the market", "both": "by both"}


def slope_t(cell):
    """A slope with its Newey-West t, as the tables print it: +0.50 (+5.0)."""
    s, t = cell["slope"], cell["t"]
    if not np.isfinite(s):
        return "n/a"
    return f"{s:+.2f} ({t:+.1f})" if np.isfinite(t) else f"{s:+.2f}"


def spread(cell):
    """The non-overlapping slopes' mean and range: +0.49 [+0.36, +0.70]."""
    no = cell["nonoverlap"]
    if not np.isfinite(no["mean"]):
        return "n/a"
    return f"{no['mean']:+.2f} [{no['min']:+.2f}, {no['max']:+.2f}]"


def share(x):
    return f"{x:.0%}" if np.isfinite(x) else "n/a"


def direction(cell):
    """Where the policy rate went, in words: toward the market's side, toward the rule's, or no clear direction."""
    if not (np.isfinite(cell["t"]) and abs(cell["t"]) >= credit.Z95):
        return "with no clear direction"
    return "toward the market's side" if cell["slope"] > 0 else "toward the rule's side"


def reading(f, labels):
    """The sentence under a currency's table, at one horizon's fit `f`."""
    m, r, p = f["market"], f["rule"], f["rate"]
    if f["who"] == "neither":
        head = (f"Over {f['h']} sessions the gap does not close: the market moves {m['slope']:+.2f} per bp of "
                f"de-meaned gap (t {m['t']:+.1f}) and the rule {r['slope']:+.2f} (t {r['t']:+.1f}).")
    else:
        head = (f"Over {f['h']} sessions {f['closed']:.2f} of the de-meaned gap closes, {WHO[f['who']]}: the rule "
                f"moves {r['slope']:+.2f} per bp (t {r['t']:+.1f}) and the market {m['slope']:+.2f} "
                f"(t {m['t']:+.1f}), so the rule does {share(f['rule_share'])} of the closing.")
    return (f"{head} The {labels['policy_rate']} in force moves {p['slope']:+.2f} per bp "
            f"(t {p['t']:+.1f}), {direction(p)}.")


def rows(r):
    """One currency's table: a row per horizon."""
    out = []
    for h, f in r["horizons"].items():
        out.append({"h": f"{h}", "sessions": f"{f['sessions']:,}", "market": slope_t(f["market"]),
                    "rule": slope_t(f["rule"]), "policy rate": slope_t(f["rate"]), "gap": slope_t(f["gap"]),
                    "closed": f"{f['closed']:.2f}" if np.isfinite(f["closed"]) else "n/a",
                    "the rule's share": share(f["rule_share"]), "rule, non-overlapping [range]": spread(f["rule"])})
    return pd.DataFrame(out)


def bin_rows(f):
    """The bins at one horizon: the edge's decile, its mean, and the mean of each change, bp."""
    return pd.DataFrame([{"decile": i + 1, "mean gap, de-meaned": f"{b['edge']:+.1f}", "market": f"{b['market']:+.1f}",
                          "rule": f"{b['rule']:+.1f}", "policy rate": f"{b['rate']:+.1f}",
                          "sessions": f"{b['sessions']:,}"} for i, b in enumerate(f["bins"])])


def markdown(results, cfgs, spans):
    """reports/closure.md: `results` {ccy: `closure.run`}, `cfgs` {ccy: its config}, `spans` {ccy: (first, last)}."""
    k = next(iter(results.values()))["k"]
    lines = [
        "# Who closes the gap: the market or the rule", "",
        HEADER + " Methods: `src/policypath/closure.py`; decisions: notes/DECISIONS.md, \"Who closes the gap\".", "",
        "- Panels: " + "; ".join(f"{c} {a:%Y-%m-%d} .. {b:%Y-%m-%d}" for c, (a, b) in spans.items()),
        f"- The meeting: the {ORDINAL.get(k, k)} ahead at each close (the one the outrights trade), held as the path "
        "moves on; a session whose meeting has left the path by the end of its window is left out.",
        "- The regressor: the gap at that meeting less its trailing window's mean at the close (the edge the z "
        "trades), on sessions with a z outside the ELB state.",
        "- The changes, bp: the market's rate for that meeting, the rule's rate for it, and the policy rate in force, "
        "from the session after the close to h sessions after that, as the IC measures them.", "",
        "The gap is market minus rule, so a negative slope on the market, or a positive one on the rule, is that side "
        "closing the gap. The gap's own slope is the market's less the rule's; the share closed is minus it, and the "
        "rule's share is its part of that. Each slope has its Newey-West t (Bartlett weights to lag h) in brackets; "
        "the non-overlapping range fits every h-th session from each of the h start offsets.", "",
    ]
    for ccy, r in results.items():
        labels = cfgs[ccy]["report"]["labels"]
        last = r["horizons"][max(r["horizons"])]
        lines += [f"## {ccy}", "",
                  f"Market: {labels['market']}. Rule: {labels['rule']}. Policy rate: {labels['policy_rate']} in force.",
                  "",
                  table(rows(r)), "", reading(last, labels), "",
                  f"### {ccy}: the bins at {last['h']} sessions", "",
                  f"The de-meaned gap's deciles over the {last['sessions']:,} sessions of the fit "
                  f"({last['first']:%Y-%m-%d} .. {last['last']:%Y-%m-%d}): the mean gap and the mean change in "
                  "each, bp.", "",
                  table(bin_rows(last)), ""]
    return "\n".join(lines)


def results_json(results, cfgs):
    """reports/results/closure.json: each currency's fits, the labels its report uses, and the reading at each
    horizon in the report's words, for the explorer."""
    out = {}
    for ccy, r in results.items():
        labels = cfgs[ccy]["report"]["labels"]
        out[ccy] = jsonable({"k": r["k"], "labels": {key: labels[key] for key in ("market", "rule", "policy_rate")},
                             "horizons": r["horizons"],
                             "reading": {h: reading(f, labels) for h, f in r["horizons"].items()}})
    return out
